  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 0);
  assert.equal(result[0].vat, 0);
  assert.equal(result[0].base, 60000);
});

test('vatSummary with mix of zero and non-zero VAT', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = vatSummary([issued]);

  assert.equal(result.length, 2);
  assert.equal(result[0].rate, 21);
  assert.equal(result[1].rate, 0);
  assert.equal(result[1].vat, 0);
});

test('vatSummary includes base without tier discount for standard customer', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = vatSummary([issued]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  const lineTotal = 8500;
  assert.equal(result[0].base, lineTotal);
});

test('vatSummary with multiple lines same rate consolidates', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'DES-HOUR', qty: 2 },
    ],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = vatSummary([issued]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.ok(result[0].base > 0);
  assert.ok(result[0].vat > 0);
});

test('vatSummary VAT calculated on reduced base', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 50 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = vatSummary([issued]);

  assert.equal(result.length, 1);
  const lineTotal = 10 * 8500;
  const discount = Math.round(lineTotal * 50 / 100);
  const expectedBase = lineTotal - discount;
  const expectedVat = Math.round(expectedBase * 21 / 100);
  assert.equal(result[0].base, expectedBase);
  assert.equal(result[0].vat, expectedVat);
});

