    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv, []).value;
  const partial1 = recordPayment(issued, { amount: 40000, date: '2026-10-20' }).value;

  const fee = lateFee(partial1, '2026-10-25');
  const balance = 85000 - 40000;
