  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2026-10-25' }).value;

  const result = lateFee(paid, '2026-10-30');
  assert.equal(result, 0);
});

